/**
 *
 * The useToast manages the state and functionality of a toast component.
 *
 * [Live Demo](https://www.primereact.org/toast/)
 *
 * @module useToaster
 * @group headless
 *
 */
import type { HeadlessInstance } from '@primereact/types/core';
import type { ToastId, ToastType } from '@primereact/types/primitive/toaster';
/**
 * Toaster position type
 */
export type ToasterPosition = 'top-left' | 'top-center' | 'top-right' | 'bottom-left' | 'bottom-center' | 'bottom-right' | 'center';
/**
 * Toaster swipe direction type
 */
export type ToasterSwipeDirection = 'left' | 'right' | 'up' | 'down';
/**
 * Toaster layout mode.
 * - `stacked`: toasts collapse into a stack and expand on hover/focus.
 * - `expanded`: every toast renders expanded; auto-dismiss only pauses while hovered.
 */
export type ToasterMode = 'expanded' | 'stacked';
/**
 * Defines valid properties in useToaster.
 */
export interface UseToasterProps {
    /**
     * Position of the toaster container
     * @default 'top-right'
     */
    position?: ToasterPosition;
    /**
     * Layout mode of the toaster.
     * @default 'stacked'
     */
    mode?: ToasterMode;
    /**
     * Maximum number of toasts to be visible
     * @default 3
     */
    limit?: number;
    /**
     * Gap between toasts in pixels
     * @default 14
     */
    gap?: number;
    /**
     * Timeout for toast auto-dismiss (alias for duration)
     * @default 6000
     */
    timeout?: number;
    /**
     * Group identifier for toast grouping
     */
    group?: string;
}
/**
 * Defines valid state in useToaster.
 */
export interface UseToasterState {
    /**
     * Whether the toaster container is expanded (showing all toasts).
     * In `single` mode this is always true; in `stacked` mode it follows hover/focus.
     */
    isExpanded: boolean;
    /**
     * Whether the user is currently hovering or has focus within the toast region.
     * Used to pause auto-dismiss timers independently of the visual expanded state.
     */
    isHovered: boolean;
    /**
     * Whether user is currently interacting with toasts
     */
    isInteracting: boolean;
    /**
     * Cached heights of rendered toasts for stacking calculations
     */
    heights: Array<{
        toastId: ToastId;
        height: number;
    }>;
}
/**
 * Defines the methods and properties exposed by useToaster.
 */
export interface UseToasterExposes {
    /**
     * Array of filtered toasts for the current group
     */
    toasts: ToastType[];
    /**
     * Pre-built props for the toaster root element
     */
    rootProps: Record<string, unknown>;
    /**
     * Pre-built props for the toaster region element
     */
    regionProps: Record<string, unknown>;
    /**
     * Handler for mouse enter on the toast region
     */
    onRegionMouseEnter: () => void;
    /**
     * Handler for mouse move on the toast region
     */
    onRegionMouseMove: () => void;
    /**
     * Handler for mouse leave on the toast region
     */
    onRegionMouseLeave: () => void;
    /**
     * Handler for drag end on the toast region
     */
    onRegionDragEnd: () => void;
    /**
     * Handler for pointer down on the toast region
     */
    onRegionPointerDown: (event: React.PointerEvent) => void;
    /**
     * Handler for pointer up on the toast region
     */
    onRegionPointerUp: () => void;
    /**
     * Handler for focus events within the toast region
     */
    onRegionFocus: (event: React.FocusEvent<HTMLElement>) => void;
    /**
     * Handler for blur events leaving the toast region
     */
    onRegionBlur: (event: React.FocusEvent<HTMLElement>) => void;
    /**
     * Function to update the heights state
     */
    setHeights: React.Dispatch<React.SetStateAction<Array<{
        height: number;
        toastId: ToastId;
    }>>>;
    /**
     * Marks a toast as removed in the toaster's local queue. Called by the
     * per-toast hook after its exit animation completes; the toast is then
     * filtered out of the rendered list.
     */
    removeFromQueue: (id: ToastId) => void;
    /**
     * Handler for managing focus when a toast is dismissed
     */
    handleFocusManagement: (toastElement: HTMLElement | null) => void;
}
/**
 * Instance of useToast headless.
 */
export type UseToasterInstance = HeadlessInstance<UseToasterProps, UseToasterState, UseToasterExposes>;
